    def superEggDrop(self, e: int, f: int) -> int:
        dp = [[-1 for _ in range(e+1)] for _ in range(f+1)]

        def solve(floors,eggs):

            if eggs==1:
                dp[floors][eggs] = floors
                return floors

            if floors==0:
                dp[floors][eggs] = 0
                return 0

